html:
{%- set cur = doc.currency -%}
<style>
 .apw-ws { font-family: "Helvetica Neue", Arial, "Noto Naskh Arabic", sans-serif; font-size: 10.5px; color: #1b2a33; }
 .apw-ws .hdr { display: flex; justify-content: space-between; border-bottom: 3px solid #0F3D56; padding-bottom: 8px; margin-bottom: 10px; }
 .apw-ws .ttl { font-size: 17px; font-weight: 700; color: #0F3D56; }
 .apw-ws .ar { direction: rtl; text-align: right; font-size: 15px; font-weight: 700; color: #0F3D56; }
 .apw-ws table { width: 100%; border-collapse: collapse; }
 .apw-ws th { background: #0F3D56; color: #fff; padding: 5px 4px; font-weight: 600; font-size: 9.5px; }
 .apw-ws th small { display: block; font-weight: 400; opacity: .85; }
 .apw-ws td { padding: 4px; border-bottom: 1px solid #dde5ea; }
 .apw-ws .num { text-align: right; white-space: nowrap; }
 .apw-ws .tot td { font-weight: 700; background: #f4f7f9; border-top: 2px solid #0F3D56; }
 .apw-ws .meta td { border: none; padding: 2px 4px; }
 .apw-ws .sig { margin-top: 36px; display: flex; justify-content: space-between; }
 .apw-ws .sig div { width: 30%; border-top: 1px solid #1b2a33; padding-top: 4px; text-align: center; }
</style>
<div class="apw-ws">
 <div class="hdr">
  <div><div class="ttl">Piece-Rate Wage Statement</div><div>{{ doc.company }}</div></div>
  <div class="ar">كشف أجور العمل بالقطعة<div style="font-size:10px;font-weight:400">{{ doc.name }}</div></div>
 </div>
 <table class="meta">
  <tr><td><b>Period / الفترة:</b> {{ frappe.utils.formatdate(doc.from_date) }} – {{ frappe.utils.formatdate(doc.to_date) }}</td>
      <td><b>Posting Date / تاريخ الترحيل:</b> {{ frappe.utils.formatdate(doc.posting_date) }}</td>
      <td><b>Status / الحالة:</b> {{ doc.status }}</td></tr>
 </table>
 <table style="margin-top:8px">
  <thead><tr>
   <th>#</th><th>Employee<small>الموظف</small></th><th class="num">Days<small>أيام</small></th><th class="num">Pieces<small>القطع</small></th>
   <th class="num">Gross<small>الإجمالي</small></th><th class="num">Incentive<small>الحوافز</small></th><th class="num">Rework<small>إعادة العمل</small></th>
   <th class="num">QC Ded.<small>خصم الجودة</small></th><th class="num">Cap Waiver<small>إعفاء نظامي</small></th><th class="num">Top-up<small>تكملة الحد الأدنى</small></th>
   <th class="num">Net<small>الصافي</small></th>
  </tr></thead>
  <tbody>
  {%- for r in doc.employees %}
   <tr><td>{{ loop.index }}</td><td>{{ r.employee_name or r.employee }}<br><span style="color:#6b7c86">{{ r.employee }}</span></td>
    <td class="num">{{ r.days_worked }}</td><td class="num">{{ frappe.utils.fmt_money(r.pieces, precision=0) }}</td>
    <td class="num">{{ frappe.utils.fmt_money(r.gross_earnings, currency=cur) }}</td><td class="num">{{ frappe.utils.fmt_money(r.slab_incentive, currency=cur) }}</td>
    <td class="num">{{ frappe.utils.fmt_money(r.rework_earnings, currency=cur) }}</td><td class="num">{{ frappe.utils.fmt_money(r.qc_deductions, currency=cur) }}</td>
    <td class="num">{{ frappe.utils.fmt_money(r.deduction_cap_adjustment, currency=cur) }}</td><td class="num">{{ frappe.utils.fmt_money(r.minimum_topup, currency=cur) }}</td>
    <td class="num"><b>{{ frappe.utils.fmt_money(r.net_payable, currency=cur) }}</b></td></tr>
  {%- endfor %}
   <tr class="tot"><td></td><td>Total / المجموع ({{ doc.total_employees }})</td><td></td><td class="num">{{ frappe.utils.fmt_money(doc.total_pieces, precision=0) }}</td>
    <td class="num">{{ frappe.utils.fmt_money(doc.total_gross, currency=cur) }}</td><td class="num">{{ frappe.utils.fmt_money(doc.total_slab_incentive, currency=cur) }}</td>
    <td class="num">{{ frappe.utils.fmt_money(doc.total_rework_earnings, currency=cur) }}</td><td class="num">{{ frappe.utils.fmt_money(doc.total_deductions, currency=cur) }}</td>
    <td class="num">{{ frappe.utils.fmt_money(doc.total_cap_adjustment, currency=cur) }}</td><td class="num">{{ frappe.utils.fmt_money(doc.total_minimum_topup, currency=cur) }}</td>
    <td class="num">{{ frappe.utils.fmt_money(doc.total_net, currency=cur) }}</td></tr>
  </tbody>
 </table>
 <div class="sig"><div>Prepared by / أعده</div><div>Production Manager / مدير الإنتاج</div><div>Finance / المالية</div></div>
</div>
